export const PATTERNS: Record<string, Pattern> = {
  "sensitive_path": {
    "source": "(\\.env\\b(?!\\.example)|credentials|\\.aws|\\.ssh|id_rsa|id_ed25519|\\.pem\\b|\\.key\\b|secret|token|\\.netrc|\\.npmrc|\\.pypirc|\\.kube|_history|\\.pi/agent|keychain)",
    "flags": "i"
  },
  "encoded_exec": {
    "source": "(base64\\s+(-d|--decode|-D)|xxd\\s+-r|openssl\\s+(base64|enc)\\s+-d)[^|;&]*\\|\\s*(ba|z|da)?sh\\b|(eval|exec)\\s+[\\\"']?\\$\\((echo|printf)[^)]*\\|\\s*(base64|xxd)|\\b(ba)?sh\\s+-c\\s+[\\\"']?\\$\\([^)]*base64\\s+(-d|--decode)",
    "flags": ""
  },
  "shell_substitution": {
    "source": "[<>`]|\\$\\(",
    "flags": ""
  },
  "destroys_work": {
    "source": "git\\s+(reset\\s+--hard|checkout\\s+(--\\s+)?\\.|clean\\s+-\\w*f|restore\\s+\\.|stash\\s+(drop|clear))|\\brm\\s+-\\w*r",
    "flags": ""
  }
};

